# Check for zip codes in binary/docx files
for f in /workspace/testbed/docs/*.docx; do python3 -c "
import zipfile, re
with zipfile.ZipFile('$f') as z:
    for name in z.namelist():
        if name.endswith('.xml'):
            text = z.read(name).decode('utf-8', errors='ignore')
            if re.search(r'(zip|postal)', text, re.I) or re.search(r'\b\d{5}\b', text):
                print(f'$f :: {name}')
                # extract just lines with matches
                for line in text.split('<'):
                    if re.search(r'(zip|postal|\b\d{5}\b)', line, re.I):
                        print('  ', line[:200])
" 2>/dev/null; done

# Check the database with node
node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables);
for (const t of tables) {
  const info = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\\n--- ' + t.name + ' ---');
  console.log('Columns:', info.map(c => c.name).join(', '));
  const rows = db.prepare('SELECT * FROM ' + t.name + ' LIMIT 3').all();
  rows.forEach(r => console.log(JSON.stringify(r)));
}
db.close();
" 2>/dev/null || echo "better-sqlite3 not available"

# Try reading xlsx and docx as zip files with node
node -e "
const fs = require('fs');
const { execSync } = require('child_process');
// Try unzipping docx to find text
const files = [
  '/workspace/testbed/docs/travel_summary.docx',
  '/workspace/testbed/docs/report.docx',
  '/workspace/testbed/docs/customer_report.docx',
  '/workspace/testbed/docs/Meeting_Notes_2024_06.docx'
];
for (const f of files) {
  try {
    const out = execSync('unzip -p \"' + f + '\" word/document.xml 2>/dev/null').toString();
    // Strip XML tags to get text
    const text = out.replace(/<[^>]+>/g, ' ').replace(/\\s+/g, ' ');
    const zipMatch = text.match(/\\b\\d{5}(-\\d{4})?\\b/g);
    if (zipMatch) {
      console.log(f + ': possible zip codes: ' + zipMatch.join(', '));
      // Show context
      const idx = text.search(/\\b\\d{5}\\b/);
      if (idx > -1) console.log('  Context: ...' + text.substring(Math.max(0,idx-80), idx+80) + '...');
    }
  } catch(e) {}
}
"

# Check the SQLite database with node's built-in capabilities
node -e "
const { readFileSync } = require('fs');
const buf = readFileSync('/workspace/world.db');
// Search for zip-code-like patterns in the raw binary
const text = buf.toString('utf8', 0, buf.length);
const matches = text.match(/(zip|postal|\\b\\d{5}\\b)/gi);
if (matches) console.log('Found in world.db:', [...new Set(matches)].join(', '));
else console.log('No zip patterns found in world.db');
// Also look for address-like strings
const addrMatches = text.match(/address/gi);
if (addrMatches) console.log('Found address references:', addrMatches.length);
"

# Extract more context around zip codes in the database
node -e "
const { readFileSync } = require('fs');
const buf = readFileSync('/workspace/world.db');
const text = buf.toString('utf8', 0, buf.length);

// Find all JSON-like address blocks
const regex = /\\{[^{}]*zip[^{}]*\\}/gi;
const matches = text.match(regex);
if (matches) {
  const unique = [...new Set(matches)];
  unique.forEach(m => console.log(m));
}
"

