const { readFileSync } = require('fs');
const buf = readFileSync('/workspace/world.db');
const text = buf.toString('utf8', 0, buf.length);

// Search for Emily Carter
const regex = /[{][^{}]*Emily[^{}]*Carter[^{}]*[}]/gi;
const matches = text.match(regex);
if (matches) {
  matches.forEach(m => console.log(m));
} else {
  console.log('No direct JSON match for Emily Carter');
}

// Also search for just 'Emily' in broader context
const emilyIdx = [];
let idx = 0;
while ((idx = text.indexOf('Emily', idx)) !== -1) {
  const start = Math.max(0, idx - 200);
  const end = Math.min(text.length, idx + 200);
  const snippet = text.substring(start, end).replace(/[^\x20-\x7E]/g, ' ');
  emilyIdx.push(snippet);
  idx += 5;
}
console.log('\n--- All Emily references ---');
emilyIdx.forEach((s, i) => console.log(i + ':', s));
"

